def sig(s):return [s.st_dev,s.st_ino,s.st_mode,s.st_nlink,s.st_size,s.st_mtime_ns,s.st_ctime_ns]
def open_abs(p,folder=False):
 p=pathlib.PurePosixPath(str(p));assert p.is_absolute() and ".." not in p.parts
 d=os.open("/",os.O_RDONLY|os.O_DIRECTORY|os.O_CLOEXEC)
 try:
  for part in p.parts[1:-1]:
   q=os.open(part,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW|os.O_CLOEXEC,dir_fd=d);os.close(d);d=q
  f=os.open(p.name,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC|(os.O_DIRECTORY if folder else 0),dir_fd=d)
 finally:os.close(d)
 return f
held=[];cache={};metadata={}
def retain(p,n=None,h=None):
 p=str(p)
 if p not in cache:
  f=open_abs(p);a=os.fstat(f);assert stat.S_ISREG(a.st_mode) and a.st_nlink==1 and a.st_size<=1048576
  with os.fdopen(f,"rb",closefd=False) as q:b=q.read(a.st_size+1)
  assert sig(a)==sig(os.fstat(f)) and len(b)==a.st_size
  cache[p]=b;metadata[p]={"bytes":len(b),"sha256":hashlib.sha256(b).hexdigest()};held.append((f,sig(a),p))
 m=metadata[p]
 if n is not None:assert m["bytes"]==n,p
 if h is not None:assert m["sha256"]==h,p
 return cache[p]
def create(p,b):
 p=pathlib.Path(p);p.parent.mkdir(mode=0o700,parents=True,exist_ok=True)
 f=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
 with os.fdopen(f,"wb") as q:q.write(b);q.flush();os.fsync(q.fileno())
 assert retain(p)==b
 return {"path":str(p),**metadata[str(p)]}
